// Adds a `scheduled` (cron) handler around the worker generated by adapter-cloudflare,
// which only exports `fetch`. The cron calls /api/cron through the app itself.
import fs from 'node:fs';

const dir = '.svelte-kit/cloudflare';
fs.renameSync(`${dir}/_worker.js`, `${dir}/_sveltekit.js`);
fs.appendFileSync(`${dir}/.assetsignore`, '\n_sveltekit.js\n');
fs.writeFileSync(
	`${dir}/_worker.js`,
	`import app from './_sveltekit.js';

export default {
	fetch: app.fetch,
	async scheduled(_event, env, ctx) {
		const req = new Request(env.ORIGIN + '/api/cron', {
			method: 'POST',
			// Same-origin JSON request so SvelteKit's CSRF check accepts it.
			headers: { 'x-cron-secret': env.APP_SECRET, origin: env.ORIGIN, 'content-type': 'application/json' },
			body: '{}'
		});
		ctx.waitUntil(app.fetch(req, env, ctx).then((r) => r.text()).then((t) => console.log('cron', t)));
	}
};
`
);
console.log('wrapped worker with cron handler');
